.badge.best { background: rgba(43,245,111,.15); color: #7cffb2; }
.badge.save { background: rgba(20,241,198,.2); color: var(--accent); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.value-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.value-item { padding: 16px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface); }
