.sidebar .filter-item { display: block; padding: 10px 12px; border-radius: 10px; color: var(--muted); margin-bottom: 6px; border: 1px solid transparent; cursor: pointer; }
.sidebar .filter-item.active, .sidebar .filter-item:hover { color: var(--text); border-color: var(--border); background: var(--surface); }
