.toggle button.active { background: linear-gradient(135deg, var(--accent), var(--accent-2)); color: #081011; }
.pricing { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; margin-top: 18px; }
.pricing .plan { padding: 20px; }
.faq-item { border-bottom: 1px solid var(--border); }
.faq-q { width: 100%; text-align: left; background: none; color: var(--text); border: 0; padding: 16px 0; font-weight: 700; cursor: pointer; }
