footer { margin-top: 40px; border-top: 1px solid var(--border); background: #0b0f14; }
.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; padding: 26px 0; }
.footer-col h4 { margin: 0 0 8px; }
.footer-links a { display: block; color: var(--muted); margin-bottom: 6px; }
